namespace AnyCli;

/// <summary>
/// Describes how a typed command settings object is configured and created.
/// </summary>
/// <typeparam name="TSelf">The settings type.</typeparam>
/// <remarks>
/// Implementations are normally generated by the AnyCli source generator from
/// <see cref="ArgumentAttribute"/>, <see cref="VariadicArgumentAttribute"/>, and
/// <see cref="OptionAttribute"/> members.
/// </remarks>
public interface ICommandSettings<TSelf>
    where TSelf : class, ICommandSettings<TSelf>
{
    /// <summary>
    /// Defines the arguments and options for the settings type.
    /// </summary>
    /// <param name="settings">The settings builder.</param>
    static abstract void Configure(CommandSettingsBuilder settings);

    /// <summary>
    /// Creates settings from parsed command arguments.
    /// </summary>
    /// <param name="arguments">The parsed arguments.</param>
    /// <returns>The settings instance.</returns>
    static abstract TSelf Bind(CommandArguments arguments);
}
